mapper.select:
SELECT TAB.*,(SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code_value = tab.notice_type and v.code = 'AST008.NOTICE_TYPE')as notice_type_desc, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code_value = tab.print_status and v.code = 'AST.PRINT_STATUS')as print_status_desc FROM ( select HBM.BP_NAME, fc.CONTRACT_ID, fc.CONTRACT_NAME, fc.CONTRACT_NUMBER, fc.APPROVAL_NUMBER, hci.description as cf_project, CASE WHEN nvl(fqc.FINE_DAYS, 0) > 0 or (fqc.cf_item = 45) THEN 'DEFAULT' WHEN (fqc.cf_item = 57) THEN 'FEE' WHEN (fqc.cf_item in (54,55)) THEN 'ACCOUNTA_RECEIVABLE' ELSE 'PAY' END NOTICE_TYPE, nvl(fqc.PRINT_STATUS, 'N') AS PRINT_STATUS, fqc.QUOTATION_CASHFLOW_ID, fqc.QUOTATION_ID, fqc.CF_ITEM, fqc.CF_TYPE, fqc.CALC_DATE, fqc.CF_DIRECTION, fqc.WRITE_OFF_FLAG, CASE WHEN fqc.WRITE_OFF_FLAG = 'FULL' THEN '完全核销' WHEN fqc.WRITE_OFF_FLAG = 'PARTIAL' THEN '部分核销' ELSE '未核销' END WRITE_OFF_FLAG_DESC, fqc.TIMES, fqc.DUE_AMOUNT, fqc.DUE_DATE, fqc.FINE_DAYS, 'FCT_CONTRACT' DOCUMENT_CATEGORY from FCT_QUOTATION_CASHFLOW fqc join fct_contract fc on fqc.CONTRACT_ID = fc.CONTRACT_ID JOIN FCT_PROJECT_BP fpb ON fpb.project_id = fc.project_id JOIN HLS_BP_MASTER HBM ON HBM.BP_ID = fpb.BP_ID JOIN hls_cashflow_item hci ON hci.CF_ITEM = fqc.CF_ITEM where fc.DATA_CLASS = 'NORMAL' AND FC.CONTRACT_STATUS != 'END' AND fc.DOCUMENT_CATEGORY = 'FCT_CONTRACT' AND fqc.CF_DIRECTION = 'INFLOW' AND FQC.CF_STATUS != 'BLOCK' and fpb.credit_grantor_party = 'Y' and fqc.CONTRACT_ID != 0 and ((fqc.times = 0 and fqc.cf_item = 55) or (fqc.times != 0 and (fc.CONTRACT_STATUS = 'INCEPT' or (fc.CONTRACT_STATUS = 'PENDING' AND ( SELECT COUNT(1) FROM FCT_CONTRACT FT WHERE FT.DATA_CLASS = 'CHANGE_REQ' AND FT.CONTRACT_STATUS = 'INCEPT' AND FT.REF_CONTRACT_ID = fc.CONTRACT_ID ) > 0)))) union all SELECT HBM.BP_NAME, fc.CONTRACT_ID, fc.CONTRACT_NAME, fc.CONTRACT_NUMBER, fp.APPROVAL_NUMBER, hci.description AS cf_project, CASE WHEN nvl(fqc.FINE_DAYS, 0) > 0 or (fqc.cf_item = 9) THEN 'DEFAULT' WHEN (fqc.cf_item = 4) THEN 'FEE' ELSE 'PAY' END NOTICE_TYPE, nvl(fqc.PRINT_STATUS, 'N') AS PRINT_STATUS, fqc.CASHFLOW_ID, fqc.QUOTATION_ID, fqc.CF_ITEM, fqc.CF_TYPE, fqc.CALC_DATE, fqc.CF_DIRECTION, fqc.WRITE_OFF_FLAG, CASE WHEN fqc.WRITE_OFF_FLAG = 'FULL' THEN '完全核销' WHEN fqc.WRITE_OFF_FLAG = 'PARTIAL' THEN '部分核销' ELSE '未核销' END WRITE_OFF_FLAG_DESC, fqc.TIMES, fqc.DUE_AMOUNT, fqc.DUE_DATE, fqc.FINE_DAYS, 'CON_CONTRACT' DOCUMENT_CATEGORY FROM con_contract_cashflow fqc JOIN con_contract fc ON fqc.CONTRACT_ID = fc.CONTRACT_ID JOIN prj_project fp ON fp.project_id = fc.PROJECT_ID JOIN HLS_BP_MASTER HBM ON HBM.BP_ID = fc.TENANT_ID JOIN hls_cashflow_item hci ON hci.CF_ITEM = fqc.CF_ITEM WHERE fc.DATA_CLASS = 'NORMAL' AND FC.CONTRACT_STATUS != 'END' AND fc.DOCUMENT_CATEGORY = 'CON_CONTRACT' AND fqc.CF_DIRECTION = 'INFLOW' AND FQC.CF_STATUS != 'BLOCK' AND fqc.CONTRACT_ID != 0 and (fqc.CF_ITEM = 10 or (fqc.times = 0 and fqc.cf_item = 1) or (fqc.times != 0 and (fc.CONTRACT_STATUS = 'INCEPT' or (fc.CONTRACT_STATUS = 'PENDING' AND ( SELECT COUNT(1) FROM FCT_CONTRACT FT WHERE FT.DATA_CLASS = 'CHANGE_REQ' AND FT.CONTRACT_STATUS = 'INCEPT' AND FT.REF_CONTRACT_ID = fc.CONTRACT_ID ) > 0))))) TAB
and ( TAB.APPROVAL_NUMBER like '%'||#{approvalNumber}||'%' OR TAB.BP_NAME like '%'||#{approvalNumber}||'%' )
AND TAB.CONTRACT_ID = #{contractId}
and TAB.contract_number like '%'||#{contractNumber}||'%'
AND TAB.DOCUMENT_CATEGORY = #{documentCategory}
AND TAB.TIMES = #{times}
AND TAB.NOTICE_TYPE = #{noticeType}
AND to_char(TAB.DUE_DATE, 'YYYY-MM-DD') >= #{dueDateStart}
AND to_char(TAB.DUE_DATE, 'YYYY-MM-DD') <= #{dueDateEnd}
AND TAB.write_off_flag = #{writeOffFlag}
AND TAB.print_status = #{printStatus}
AND TAB.NOTICE_TYPE IN('PAY' ,'FEE','ACCOUNTA_RECEIVABLE')
AND TAB.NOTICE_TYPE = 'DEFAULT'
AND TAB.BP_NAME like concat(concat('%',#{bpName}),'%')
AND TAB.CF_PROJECT LIKE '%'|| #{cfProject,jdbcType=VARCHAR}||'%'
AND TAB.FINE_DAYS = 1
AND WRITE_OFF_FLAG !='FULL'
ORDER BY TAB.PRINT_STATUS,TAB.DUE_DATE

SELECT CON.* FROM ( SELECT MIN (fct.quotation_cashflow_id) quotation_cashflow_id, FCT.bp_id, FCT.address, FCT.personName, FCT.cellPhone, FCT.contract_id, FCT.contract_number, FCT.times, FCT.NOTICE_TYPE, FCT.DOCUMENT_CATEGORY, MAX(FCT.PRINT_STATUS) PRINT_STATUS FROM ( SELECT cc.quotation_cashflow_id, CASE WHEN cc.cf_item=54 THEN prp.bp_id WHEN cc.cf_item=51 THEN pgp.bp_id ELSE ( CASE fp.fund_restream_method WHEN 'DIRECT' THEN psr.bp_id ELSE pby.bp_id END) END bp_id, CASE WHEN cc.cf_item=54 THEN prp.address WHEN cc.cf_item=51 THEN pgp.address ELSE ( CASE fp.fund_restream_method WHEN 'DIRECT' THEN psr.address ELSE pby.address END) END address, CASE WHEN cc.cf_item=54 THEN prp.contact_person WHEN cc.cf_item=51 THEN pgp.contact_person ELSE ( CASE fp.fund_restream_method WHEN 'DIRECT' THEN psr.contact_person ELSE pby.contact_person END) END personName, CASE WHEN cc.cf_item=54 THEN prp.cell_phone WHEN cc.cf_item=51 THEN pgp.cell_phone ELSE ( CASE fp.fund_restream_method WHEN 'DIRECT' THEN psr.cell_phone ELSE pby.cell_phone END) END cellPhone, cc.contract_id, c.contract_number, cc.times, CASE WHEN nvl(cc.FINE_DAYS,0) > 0 or (cc.cf_item=45) THEN 'DEFAULT' WHEN cc.cf_item=57 THEN 'FEE' WHEN cc.cf_item in (54,55) THEN 'ACCOUNTA_RECEIVABLE' ELSE 'PAY' END NOTICE_TYPE, 'FCT_CONTRACT' DOCUMENT_CATEGORY, nvl(cc.PRINT_STATUS,'N') AS PRINT_STATUS FROM fct_quotation_cashflow cc JOIN fct_contract c ON c.contract_id = cc.contract_id JOIN fct_project fp ON fp.project_id=c.project_id LEFT JOIN ( SELECT fpb.bp_id, fpb.project_id, concat(concat(concat(concat(ma.country, ( select t1.description from fnd_province t1 where t1.province = ma.province )), ( select t1.description from fnd_city t1 where t1.city = ma.city )), ( select t1.description from fnd_district t1 where t1.district = ma.district)), ma.address) as address, mc.contact_person, mc.cell_phone FROM fct_project_bp fpb LEFT JOIN hls_bp_master_address ma ON ma.address_id=fpb.address_id LEFT JOIN hls_bp_master_contact_info mc ON mc.contact_info_id=fpb.contact_info_id WHERE fpb.principal_repayment_party='Y') prp ON prp.project_id=c.project_id LEFT JOIN ( SELECT fpb.bp_id, fpb.project_id, concat(concat(concat(concat(ma.country, ( select t1.description from fnd_province t1 where t1.province = ma.province )), ( select t1.description from fnd_city t1 where t1.city = ma.city )), ( select t1.description from fnd_district t1 where t1.district = ma.district)), ma.address) as address, mc.contact_person, mc.cell_phone FROM fct_project_bp fpb LEFT JOIN hls_bp_master_address ma ON ma.address_id=fpb.address_id LEFT JOIN hls_bp_master_contact_info mc ON mc.contact_info_id=fpb.contact_info_id WHERE fpb.repay_guarantee_party='Y') pgp ON pgp.project_id=c.project_id LEFT JOIN ( SELECT fpb.bp_id, fpb.project_id, concat(concat(concat(concat(ma.country, ( select t1.description from fnd_province t1 where t1.province = ma.province )), ( select t1.description from fnd_city t1 where t1.city = ma.city )), ( select t1.description from fnd_district t1 where t1.district = ma.district)), ma.address) as address, mc.contact_person, mc.cell_phone FROM fct_project_bp fpb LEFT JOIN hls_bp_master_address ma ON ma.address_id=fpb.address_id LEFT JOIN hls_bp_master_contact_info mc ON mc.contact_info_id=fpb.contact_info_id WHERE fpb.bp_role_type='SELLER') psr ON psr.project_id=c.project_id LEFT JOIN ( SELECT fpb.bp_id, fpb.project_id, concat(concat(concat(concat(ma.country, ( select t1.description from fnd_province t1 where t1.province = ma.province )), ( select t1.description from fnd_city t1 where t1.city = ma.city )), ( select t1.description from fnd_district t1 where t1.district = ma.district)), ma.address) as address, mc.contact_person, mc.cell_phone FROM fct_project_bp fpb LEFT JOIN hls_bp_master_address ma ON ma.address_id=fpb.address_id LEFT JOIN hls_bp_master_contact_info mc ON mc.contact_info_id=fpb.contact_info_id WHERE fpb.bp_role_type='BUYER') pby ON pby.project_id=c.project_id WHERE ('FCT_CONTRACT'||cc.quotation_cashflow_id) in
#{item}
) FCT GROUP BY FCT.bp_id,FCT.address,FCT.personName,FCT.cellPhone, FCT.contract_id,FCT.contract_number,FCT.times,FCT.NOTICE_TYPE,FCT.DOCUMENT_CATEGORY
UNION
SELECT MIN (CCT.cashflow_id) quotation_cashflow_id, CCT.bp_id, CCT.address, CCT.personName, CCT.cellPhone, CCT.contract_id, CCT.contract_number, CCT.times, CCT.NOTICE_TYPE, CCT.DOCUMENT_CATEGORY, MAX(CCT.PRINT_STATUS) PRINT_STATUS FROM ( SELECT cc.cashflow_id, pp.bp_id, pp.address, pp.contact_person personName, pp.cell_phone cellPhone, cc.contract_id, c.contract_number, cc.times, CASE WHEN nvl(cc.FINE_DAYS,0) > 0 OR (cc.cf_item=9) THEN 'DEFAULT' WHEN cc.cf_item=4 THEN 'FEE' ELSE 'PAY' END NOTICE_TYPE, 'CON_CONTRACT' DOCUMENT_CATEGORY, nvl(cc.PRINT_STATUS,'N') AS PRINT_STATUS FROM con_contract_cashflow cc JOIN con_contract c ON cc.CONTRACT_ID=c.CONTRACT_ID LEFT JOIN ( SELECT fpb.bp_id, fpb.project_id, concat(concat(concat(concat(ma.country, ( SELECT t1.description FROM fnd_province t1 WHERE t1.province = ma.province )), ( SELECT t1.description FROM fnd_city t1 WHERE t1.city = ma.city )), ( SELECT t1.description FROM fnd_district t1 WHERE t1.district = ma.district)), ma.address) AS address, mc.contact_person, mc.cell_phone FROM prj_project_bp fpb LEFT JOIN hls_bp_master_address ma ON ma.address_id=fpb.address_id LEFT JOIN hls_bp_master_contact_info mc ON mc.contact_info_id=fpb.contact_info_id WHERE fpb.BP_TYPE='TENANT') pp ON pp.project_id=c.project_id WHERE ('CON_CONTRACT'||cc.cashflow_id) in
#{item}
) CCT GROUP BY CCT.bp_id,CCT.address,CCT.personName,CCT.cellPhone, CCT.contract_id,CCT.contract_number,CCT.times,CCT.NOTICE_TYPE,CCT.DOCUMENT_CATEGORY ) CON
